export type ParsedProjectFile = { ok: true; data: ProjectData } | { ok: false; error: string }

export function parseProjectFile(fileText: string): ParsedProjectFile {
  let raw: unknown
  try {
    raw = JSON.parse(fileText)
  } catch {
    return { ok: false, error: 'Súbor nie je platný JSON' }
  }
  if (!isProjectFile(raw)) return { ok: false, error: 'Súbor nie je projekt Table Maker' }
  if (versionOf(record(raw)) > DATA_VERSION) return { ok: false, error: 'Súbor pochádza z novšej verzie aplikácie' }
  return { ok: true, data: decodeProjectData(raw) }
}

// Trims and cuts text to at most `max` UTF-16 units without splitting a surrogate pair.
export function limitText(value: string, max: number): string {
  const s = value.trim()
  if (s.length <= max) return s
  let cut = s.slice(0, max)
  if (/[\uD800-\uDBFF]$/.test(cut)) cut = cut.slice(0, -1)
  return cut.trimEnd()
}

// Project name for "import as new project": the file name without .json, within the name limit.
export function projectNameFromFile(fileName: string): string {
  return limitText(fileName.replace(/\.json$/i, ''), PROJECT_NAME_MAX) || 'Importovaný projekt'
}
